import { useState } from 'react';
import {
  FiActivity, FiArrowRight, FiBarChart2, FiBell, FiBookOpen, FiBox,
  FiCheck, FiChevronDown, FiCloud, FiCode, FiGrid, FiHeart, FiHome,
  FiLayers, FiMail, FiMapPin, FiMenu, FiMonitor, FiPackage, FiPhone,
  FiPlus, FiSearch, FiSettings, FiShoppingCart, FiSmartphone, FiTrendingUp,
  FiUsers, FiX
} from 'react-icons/fi';
import logo from './assets/logo.png';

const navItems = ['Home', 'Solutions', 'Industries', 'Products', 'Technology', 'Company'];
const solutions = [
  [FiLayers, 'Hospital ERP', 'Complete hospital management with OPD, IPD, Pharmacy, Lab, Billing & more.', 'blue'],
  [FiActivity, 'Pharmacy ERP', 'Manage inventory, sales, purchases, GST, expiry and more.', 'mint'],
  [FiBookOpen, 'Pathology Software', 'Lab management, test reports, QR reports, sample tracking and analytics.', 'violet'],
  [FiBox, 'School ERP', 'Students, fees, attendance, exams, transport and communication.', 'sky'],
  [FiHome, 'College ERP', 'Admission, departments, examination, fees, library and more.', 'orange'],
  [FiMonitor, 'Website Development', 'Corporate, eCommerce, dynamic & custom web solutions.', 'blue'],
  [FiSmartphone, 'Mobile App Development', 'Android, iOS & cross-platform apps that deliver exceptional experiences.', 'teal'],
  [FiCloud, 'Cloud Solutions', 'Cloud hosting, backup, scalability and security for your business.', 'blue'],
  [FiUsers, 'CRM Solutions', 'Leads, deals, tasks and customer management in one place.', 'violet'],
  [FiSettings, 'AI & Automation', 'AI chatbots, workflow automation, document processing & more.', 'blue'],
  [FiShoppingCart, 'E-Commerce Solutions', 'Powerful eCommerce platforms with payment gateway.', 'violet'],
  [FiPackage, 'Custom Software', 'Tailor-made software built as per your unique business needs.', 'blue']
];
const industries = [[FiHeart, 'Healthcare'], [FiActivity, 'Pharmacy'], [FiBookOpen, 'Education'], [FiMonitor, 'Corporate'], [FiHome, 'Real Estate'], [FiShoppingCart, 'Retail'], [FiBox, 'Logistics'], [FiBarChart2, 'Manufacturing']];
const technologies = [['React', '⚛'], ['Next.js', 'N'], ['Node.js', '⬡'], ['Python', '⌘'], ['PHP', 'php'], ['Java', '♨'], ['Laravel', '⌁'], ['MySQL', '◫'], ['MongoDB', '◉'], ['AWS', 'aws'], ['Azure', '◈'], ['Firebase', '♨'], ['Docker', '▣']];
const stories = [
  ['Hospital Management System', 'Complete solution for 100-bed multi-speciality hospital.', 'hospital'],
  ['Pharmacy ERP', 'Automated inventory & sales for retail pharmacy chain.', 'pharmacy'],
  ['Pathology Management System', 'Digital lab management & reporting system.', 'pathology'],
  ['School Management System', 'Smart school ERP for 500+ students.', 'school'],
  ['E-Commerce Platform', 'Full-stack e-commerce solution with payment gateway.', 'ecommerce']
];
const faqs = ['What services does Arnex Tech provide?', 'How long does a project typically take?', 'Do you provide custom solutions?', 'Are your solutions scalable?', 'Do you provide after-sales support?'];

const scrollTo = (id) => document.getElementById(id)?.scrollIntoView({ behavior: 'smooth', block: 'start' });

function Brand() {
  return <a className="brand" href="#home" onClick={(event) => { event.preventDefault(); scrollTo('home'); }}><img src={logo} alt="Arnex Tech" /></a>;
}

function Button({ children, ghost, onClick, type = 'button' }) {
  return <button type={type} className={`button${ghost ? ' button--ghost' : ''}`} onClick={onClick}>{children}<FiArrowRight /></button>;
}

function Proof({ icon: Icon, value, text, inverse }) {
  return <div className={`proof${inverse ? ' proof--inverse' : ''}`}><span><Icon /></span><div><b>{value}</b><small>{text}</small></div></div>;
}

function Metric({ label, value, growth }) {
  return <div className="metric"><small>{label}</small><b>{value}</b><span>↗ {growth}<em>vs last month</em></span></div>;
}

function Dashboard() {
  const sideIcons = [FiGrid, FiHome, FiBox, FiUsers, FiSettings];
  return <div className="dashboard-wrap" aria-label="Business analytics dashboard preview">
    <div className="dashboard">
      <aside className="dash-sidebar"><div className="dash-avatar">A</div>{sideIcons.map((Icon, index) => <span className={`dash-nav${index === 0 ? ' active' : ''}`} key={index}><Icon /></span>)}</aside>
      <div className="dash-main">
        <div className="dash-topbar"><div><b>Arnex Business Intelligence</b><small>Business overview</small></div><div className="dash-actions"><FiSearch /><span className="notification"><FiBell /><i /></span><span className="profile-dot">S</span></div></div>
        <div className="metrics"><Metric label="Total Revenue" value="₹24.8L" growth="24.4%"/><Metric label="Total Customers" value="2,486" growth="18.6%"/><Metric label="Total Orders" value="8,921" growth="32.4%"/><div className="metric metric--chart"><small>Top Channels</small><div className="donut"><span /></div><div className="legend"><b>Web <em>40%</em></b><b>Mobile <em>28%</em></b><b>Partner <em>20%</em></b></div></div></div>
        <div className="dash-lower"><div className="chart-card"><div className="chart-heading"><b>Sales Overview</b><small>This Year⌄</small></div><div className="line-chart"><span className="chart-grid g1"/><span className="chart-grid g2"/><span className="chart-grid g3"/><svg viewBox="0 0 430 150" preserveAspectRatio="none"><defs><linearGradient id="chartArea" x1="0" x2="0" y1="0" y2="1"><stop stopColor="#1c63ee" stopOpacity=".24"/><stop offset="1" stopColor="#1c63ee" stopOpacity="0"/></linearGradient></defs><path d="M0 125 L32 113 L67 100 L97 77 L128 91 L163 61 L198 82 L231 55 L263 72 L299 37 L332 50 L365 20 L400 33 L430 5 L430 150 L0 150Z" fill="url(#chartArea)"/><polyline points="0,125 32,113 67,100 97,77 128,91 163,61 198,82 231,55 263,72 299,37 332,50 365,20 400,33 430,5" fill="none" stroke="#2464e9" strokeWidth="3"/></svg></div><div className="months"><span>Jan</span><span>Feb</span><span>Mar</span><span>Apr</span><span>May</span><span>Jun</span><span>Jul</span></div></div><div className="orders"><div className="chart-heading"><b>Recent Orders</b><small>View all</small></div>{['#ORD1248', '#ORD1247', '#ORD1246', '#ORD1245'].map((order, index) => <div className="order" key={order}><span className="order-icon"><FiBox /></span><b>{order}</b><em className={index === 3 ? 'cancelled' : ''}>{['₹21,540', '₹18,760', '₹12,300', '₹9,890'][index]}<small>{index === 3 ? 'Cancelled' : 'Completed'}</small></em></div>)}</div></div>
      </div>
    </div>
    <div className="growth-card"><FiTrendingUp /><b>+28.4%</b><span>Sales growth</span><div className="bars"><i/><i/><i/><i/></div></div>
  </div>;
}

function SectionHeading({ overline, subtitle, action }) {
  return <div className="section-heading"><div><span className="overline">{overline}</span>{subtitle && <p>{subtitle}</p>}</div>{action && <button className="text-action">View All {overline}<FiArrowRight /></button>}</div>;
}

function SolutionCard({ item }) {
  const [Icon, title, text, tone] = item;
  return <article className="solution-card"><div className={`solution-icon ${tone}`}><Icon /></div><div><h3>{title}</h3><p>{text}</p></div><button>Learn More <FiArrowRight /></button></article>;
}

function FooterLinks({ title, links }) {
  return <div className="footer-links"><h3>{title}</h3>{links.map((link) => <a href="#home" key={link}>{link}</a>)}</div>;
}

export default function App() {
  const [menuOpen, setMenuOpen] = useState(false);
  const [activeFaq, setActiveFaq] = useState(null);
  const [submitted, setSubmitted] = useState(false);
  const jump = (id) => { setMenuOpen(false); scrollTo(id); };
  const sendForm = (event) => { event.preventDefault(); event.currentTarget.reset(); setSubmitted(true); window.setTimeout(() => setSubmitted(false), 2800); };
  const navTarget = ['home', 'solutions', 'industries', 'projects', 'technology', 'company'];

  return <main>
    <header className="site-header"><div className="nav-shell"><Brand /><nav className={`nav-links${menuOpen ? ' open' : ''}`}>{navItems.map((item, index) => <button key={item} onClick={() => jump(navTarget[index])} className={`nav-link${index === 0 ? ' selected' : ''}`}>{item}{index > 0 && <FiChevronDown />}</button>)}<button className="nav-contact" onClick={() => jump('contact')}>Contact Us</button></nav><button className="demo-button" onClick={() => jump('contact')}>Get a Demo <FiArrowRight /></button><button className="menu-toggle" aria-label="Toggle menu" onClick={() => setMenuOpen(!menuOpen)}>{menuOpen ? <FiX /> : <FiMenu />}</button></div></header>

    <section id="home" className="hero"><div className="hero-inner container"><div className="hero-copy"><span className="hero-chip"><i>✦</i> Smart Solutions for Smarter Businesses</span><h1>We Build <span>Digital<br/>Solutions</span> That<br/>Drive Growth</h1><p>Custom Software, ERP, CRM, Cloud &amp; Web Solutions designed to simplify operations, increase efficiency and accelerate your business growth.</p><div className="hero-buttons"><Button onClick={() => jump('contact')}>Start Your Project</Button><Button ghost onClick={() => jump('solutions')}>Explore Solutions</Button></div></div><Dashboard /></div><div className="container proof-row"><Proof icon={FiGrid} value="50+" text="Projects Delivered"/><Proof icon={FiLayers} value="25+" text="Industries Served"/><Proof icon={FiCheck} value="10+" text="Years of Experience"/><Proof icon={FiActivity} value="24/7" text="Support Available"/></div></section>

    <section id="solutions" className="solutions section"><div className="container"><SectionHeading overline="Our Solutions" subtitle="Powerful, Flexible & Scalable Solutions for Your Entire Business" action/><div className="solutions-grid">{solutions.map((item) => <SolutionCard item={item} key={item[1]} />)}</div></div></section>

    <section id="industries" className="industries section"><div className="container"><SectionHeading overline="Industries We Serve"/><div className="industry-grid">{industries.map(([Icon, label]) => <div className="industry-pill" key={label}><Icon />{label}</div>)}<div className="industry-pill more">••• More</div></div></div></section>

    <section id="company" className="ai-section"><div className="container ai-panel"><div className="why-list"><span className="overline">Why Choose Arnex Tech?</span><h2>Technology that makes a measurable difference.</h2>{[['⌂', 'Custom Built Solutions', 'Tailored software to match your business goals.'], ['♧', 'Scalable & Secure', 'Built with modern technology for maximum security.'], ['◉', 'Cost Effective', 'High quality solutions at affordable pricing.'], ['◷', 'On-Time Delivery', 'We deliver on time, every time.'], ['▢', '24/7 Support', 'Our team is always here to support you.']].map(([mark, title, text]) => <div className="why-item" key={title}><span>{mark}</span><div><b>{title}</b><p>{text}</p></div></div>)}</div><div className="ai-copy"><span className="overline">We Transform Businesses with</span><h2><span>AI-Powered</span><br/>Solutions</h2><p>Bring intelligence to every part of your business with practical AI built around people, process and growth.</p><ul><li>AI-Powered Business Automation</li><li>Real-time Analytics &amp; Insights</li><li>Scalable &amp; Secure Architecture</li><li>Cloud-Based Solutions</li><li>Mobile-First Approach</li><li>Dedicated Support &amp; Maintenance</li></ul><Button onClick={() => jump('contact')}>Explore AI Solutions</Button></div><div className="ai-orbit" aria-hidden="true"><span className="orbit orbit-one"/><span className="orbit orbit-two"/><div className="brain"><div className="brain-lobe one"/><div className="brain-lobe two"/><div className="brain-lobe three"/><i/><i/><i/><i/></div><div className="orbit-label label-one">⌘</div><div className="orbit-label label-two">↗</div><div className="orbit-label label-three">☁</div></div></div></section>

    <section id="technology" className="technology section"><div className="container"><SectionHeading overline="Technologies We Use"/><div className="tech-grid">{technologies.map(([name, mark]) => <div className="tech" key={name}><span>{mark}</span><small>{name}</small></div>)}</div></div></section>

    <section id="projects" className="projects section"><div className="container"><SectionHeading overline="Our Success Stories" action/><div className="stories-grid">{stories.map(([title, description, accent]) => <article className="story-card" key={title}><div className={`story-image ${accent}`}><span>{title}</span><div className="scene"><i/><i/><i/></div></div><div className="story-content"><h3>{title}</h3><p>{description}</p><button>View Case Study <FiArrowRight /></button></div></article>)}</div><div className="carousel-dots"><i className="active"/><i/><i/><i/></div></div></section>

    <section className="blue-stats"><div className="container"><Proof icon={FiGrid} value="50+" text="Projects Delivered" inverse/><Proof icon={FiLayers} value="25+" text="Industries Served" inverse/><Proof icon={FiCheck} value="10+" text="Partners & Clients" inverse/><Proof icon={FiHeart} value="98%" text="Client Satisfaction" inverse/><Proof icon={FiActivity} value="24/7" text="Support Available" inverse/></div></section>

    <section id="contact" className="bottom-section section"><div className="container bottom-grid"><div className="testimonials"><SectionHeading overline="What Our Clients Say"/><div className="quote-grid">{[['Dr. Ramesh Verma', 'City Hospital, Lucknow', 'Arnex Tech delivered an outstanding hospital management system that transformed our operations.', 'RK'], ['Anita Sharma', 'Sharma Medical Store', 'Professional team, excellent support and very reliable solutions. Highly recommended!', 'AS'], ['Varun Patel', 'CEO, Buildcon Industries', 'Their software delivery and support understanding our unique needs was excellent.', 'VP']].map(([name, company, quote, initials], index) => <div className="quote-card" key={name}><div className="stars">★★★★★</div><p>“{quote}”</p><div><span className={`person person-${index}`}>{initials}</span><b>{name}<small>{company}</small></b></div></div>)}</div></div><div className="faq"><SectionHeading overline="Frequently Asked Questions"/>{faqs.map((faq, index) => <button onClick={() => setActiveFaq(activeFaq === index ? null : index)} className={`faq-item${activeFaq === index ? ' expanded' : ''}`} key={faq}><span>{faq}<em>{activeFaq === index ? 'Absolutely — our team creates tailored software, ERP, mobile and web systems based on your exact business needs.' : ''}</em></span><FiPlus /></button>)}</div><form className="contact-card" onSubmit={sendForm}><span className="overline">Let's Build Something</span><h2>Great Together</h2><input required placeholder="Your Name"/><input required type="email" placeholder="Email Address"/><input placeholder="Phone Number"/><select defaultValue=""><option value="" disabled>Select Service</option><option>Custom Software</option><option>ERP Solution</option><option>Web Development</option><option>AI & Automation</option></select><textarea required placeholder="Your Message" rows="3"/><Button type="submit">{submitted ? 'Message Sent!' : 'Send Message'}</Button><div className="contact-details"><span><FiPhone /> +91 98384 73698</span><span><FiMail /> info@arnextech.com</span><span><FiMapPin /> Vrindavan, Lucknow<br/>Uttar Pradesh, India</span></div></form></div></section>

    <footer><div className="container footer-grid"><div className="footer-brand"><Brand /><p>We build digital solutions that help businesses grow, automate operations and achieve more.</p><div className="socials"><a href="#home">f</a><a href="#home">in</a><a href="#home">◎</a><a href="#home">▶</a></div></div><FooterLinks title="Solutions" links={['Hospital ERP', 'Pharmacy ERP', 'School ERP', 'College ERP', 'Website Development', 'Mobile App Development']}/><FooterLinks title="Company" links={['About Us', 'Our Team', 'Careers', 'Blog', 'Case Studies', 'Contact Us']}/><FooterLinks title="Support" links={['Help Center', 'FAQs', 'Privacy Policy', 'Terms & Conditions']}/></div><div className="container legal"><span>© 2026 Arnex Tech. All Rights Reserved.</span><span>Made with ♥ in India</span></div></footer>
  </main>;
}
